-- Modelo conceptual (docs/diagramas/12-modelo-datos.png). El nombre del estudiante no se almacena.
CREATE TABLE usuario (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(120) NOT NULL, correo VARCHAR(160) NOT NULL UNIQUE, hash_contrasena VARCHAR(100) NOT NULL, rol ENUM('docente','coordinador') NOT NULL);
CREATE TABLE curso (id INT AUTO_INCREMENT PRIMARY KEY, docente_id INT NOT NULL, nombre VARCHAR(160) NOT NULL, grado VARCHAR(20), asignatura VARCHAR(80), metodologia VARCHAR(120), unidad VARCHAR(160), objetivos JSON, temas JSON, materiales TEXT, FOREIGN KEY (docente_id) REFERENCES usuario(id));
CREATE TABLE rubrica (id INT AUTO_INCREMENT PRIMARY KEY, curso_id INT NOT NULL, nombre VARCHAR(160) NOT NULL, FOREIGN KEY (curso_id) REFERENCES curso(id) ON DELETE CASCADE);
CREATE TABLE criterio (id INT AUTO_INCREMENT PRIMARY KEY, rubrica_id INT NOT NULL, descripcion VARCHAR(200) NOT NULL, peso TINYINT UNSIGNED NOT NULL, FOREIGN KEY (rubrica_id) REFERENCES rubrica(id) ON DELETE CASCADE, CHECK (peso <= 100));
CREATE TABLE plan (id INT AUTO_INCREMENT PRIMARY KEY, curso_id INT NOT NULL, unidad VARCHAR(160), version INT NOT NULL DEFAULT 1, contenido JSON NOT NULL, estado ENUM('pendiente','aprobado') NOT NULL DEFAULT 'pendiente', aprobado_por INT NULL, aprobado_en DATETIME NULL, FOREIGN KEY (curso_id) REFERENCES curso(id) ON DELETE CASCADE, FOREIGN KEY (aprobado_por) REFERENCES usuario(id));
CREATE TABLE trabajo (id INT AUTO_INCREMENT PRIMARY KEY, curso_id INT NOT NULL, alias_estudiante VARCHAR(40) NOT NULL, archivo VARCHAR(255), fecha DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (curso_id) REFERENCES curso(id) ON DELETE CASCADE);
CREATE TABLE retroalimentacion (id INT AUTO_INCREMENT PRIMARY KEY, trabajo_id INT NOT NULL, criterio_id INT NOT NULL, texto_generado TEXT NOT NULL, texto_validado TEXT NULL, estado ENUM('pendiente','aprobada') NOT NULL DEFAULT 'pendiente', validado_por INT NULL, validado_en DATETIME NULL, FOREIGN KEY (trabajo_id) REFERENCES trabajo(id) ON DELETE CASCADE, FOREIGN KEY (criterio_id) REFERENCES criterio(id), FOREIGN KEY (validado_por) REFERENCES usuario(id));
